import './App.css';
import LightPillar from './LightPillar';
import { Parallax, ParallaxProvider } from 'react-scroll-parallax';

function App() {
  return (
    <ParallaxProvider>
      <div
        className="App"
        style={{
          position: 'relative',
          overflowX: 'hidden',
          background: '#0a0a0a',
          color: 'white',
        }}
      >

        {/* Background Parallax Layer */}
        <Parallax speed={-10}>
          <div
            id="pillar"
            style={{
              width: '100%',
              height: '100vh',
              position: 'fixed',
              top: 0,
              left: 0,
              zIndex: -1,
            }}
          >
            <LightPillar
              topColor="#ce466f"
              bottomColor="#ce466f"
              intensity={1}
              rotationSpeed={0.3}
              glowAmount={0.002}
              pillarWidth={3}
              pillarHeight={0.4}
              noiseIntensity={0.5}
              pillarRotation={25}
              interactive={false}
              mixBlendMode="screen"
              quality="high"
            />
          </div>
        </Parallax>

        {/* HERO SECTION */}
        <section
          id="hero"
          style={{
            height: '100vh',
            display: 'flex',
            flexDirection: 'column',
            justifyContent: 'center',
            alignItems: 'center',
            textAlign: 'center',
            padding: '2rem',
          }}
        >
          {/* NAVBAR */}
          <div
            id="navbar"
            style={{
              position: 'absolute',
              top: 20,
              left: 20,
              right: 20,
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center',
            }}
          >
            <svg
              id="logo"
              width="26"
              height="45"
              viewBox="0 0 26 45"
              fill="none"
              xmlns="http://www.w3.org/2000/svg"
            >
              <path
                d="M0.3975 30L6.7015 7.6H10.5415L16.9095 30H14.1895L9.1335 11.632L8.8775 9.936C8.85617 9.808 8.7815 9.744 8.6535 9.744C8.54683 9.744 8.48283 9.808 8.4615 9.936L8.1735 11.632L3.1175 30H0.3975ZM3.8535 24.016L4.5575 21.648H12.7495L13.4535 24.016H3.8535ZM3.0535 9.936V7.6H7.5655V9.936H3.0535Z"
                fill="white"
              />
              <path
                d="M13.7342 33V16.2H15.7262V31.128H21.7022V33H13.7342Z"
                fill="white"
              />
            </svg>

            <div id="elements">
              Navigation
            </div>
          </div>

          {/* TITLE */}
          <h1
            id="title"
            style={{
              fontSize: '4rem',
              maxWidth: '900px',
              marginBottom: '1rem',
            }}
          >
            Welcome to your Algorithm Learning Assistant!
          </h1>

          {/* SUBTITLE */}
          <p
            id="logo-underbox"
            style={{
              fontSize: '1.2rem',
              opacity: 0.8,
              marginBottom: '2rem',
            }}
          >
            Completely open-source, and free!
          </p>

          {/* BUTTON */}
          <button
            id="get-started-button"
            style={{
              padding: '1rem 2rem',
              fontSize: '1rem',
              borderRadius: '12px',
              border: 'none',
              cursor: 'pointer',
              background: '#ce466f',
              color: 'white',
              fontWeight: 'bold',
            }}
          >
            Get Started!
          </button>
        </section>

        {/* SCROLL SECTION */}
        <section
          id="overview"
          style={{
            height: '200vh',
            padding: '4rem',
            background: 'rgba(0,0,0,0.4)',
            backdropFilter: 'blur(10px)',
          }}
        >
          <h2>Overview</h2>

          <p style={{ maxWidth: '700px', lineHeight: '1.8' }}>
            Scroll down to test the parallax effect. The LightPillar
            background should move more slowly than the foreground content.
          </p>
        </section>

      </div>
    </ParallaxProvider>
  );
}

export default App;
